svg.metadata:
{"project": "EvidenceGraph", "diagram": "01_system_architecture", "title": "EvidenceGraph — High-Level System Architecture", "description": "Overview of the EvidenceGraph infrastructure: Next.js user experience, Bun.js Hono API with SSE, Valkey/BullMQ queues, independent research and ingestion workers, LangGraph orchestration and RAG, PostgreSQL, Qdrant, Neo4j, S3/MinIO, external LLM and web integrations, and LangSmith observability.", "source_format": "graphviz_dot", "graphviz_dot": "digraph EvidenceGraphSystem {
 graph [label="EVIDENCEGRAPH / SYSTEM ARCHITECTURE", labelloc=t, labeljust=l,
 fontsize=25, fontname="DejaVu Sans", fontcolor="#142338", bgcolor="#FFFFFF",
 rankdir=TB, pad=0.36, nodesep=0.55, ranksep=0.64,
 splines=polyline, compound=true, newrank=true, outputorder=edgesfirst];
 node [shape=box, style="rounded,filled", fontname="DejaVu Sans", fontsize=13,
 color="#CBD5E1", fillcolor="#FFFFFF", fontcolor="#172E44", penwidth=1.4,
 margin="0.22,0.15"];
 edge [color="#7D91A9", penwidth=1.55, arrowsize=0.75, fontsize=10,
 fontname="DejaVu Sans", fontcolor="#64748B"];

 user [label="RESEARCHER", shape=ellipse, fillcolor="#EFF6FF", color="#8CB4EA", fontsize=13];

 subgraph cluster_ui {
 label="01 / USER EXPERIENCE"; labelloc=t; labeljust=l; fontsize=14;
 style="rounded,filled"; color="#D6E4F5"; fillcolor="#F5F9FF"; margin=17;
 ui [label="Next.js + Tailwind CSS\nResearch workspace · Document upload\nReports · Graph visualization", fillcolor="#E1EDFE", color="#76A5D9"];
 }

 subgraph cluster_api {
 label="02 / API & STREAMING"; labelloc=t; labeljust=l; fontsize=14;
 style="rounded,filled"; color="#D6E4F5"; fillcolor="#F5F9FF"; margin=17;
 api [label="Bun.js + Hono API\nAuth · Zod · Input guardrails", fillcolor="#E1EDFE", color="#76A5D9"];
 sse [label="SSE progress stream\nRun events and status", fillcolor="#E1EDFE", color="#76A5D9"];
 {rank=same; api; sse}
 }

 subgraph cluster_queue {
 label="03 / ASYNCHRONOUS DELIVERY"; labelloc=t; labeljust=l; fontsize=14;
 style="rounded,filled"; color="#E5D7F1"; fillcolor="#FAF7FD"; margin=17;
 valkey [label="Valkey + BullMQ\nResearch & ingestion queues\nRetries · Cancellation · Events", fillcolor="#EFE4FC", color="#AA83CC"];
 }

 subgraph cluster_workers {
 label="04 / BACKGROUND EXECUTION"; labelloc=t; labeljust=l; fontsize=14;
 style="rounded,filled"; color="#D1E8DC"; fillcolor="#F3FBF6"; margin=17;
 rw [label="Bun research worker\nAgent execution + task lifecycle", fillcolor="#DAF1E4", color="#76B894"];
 iw [label="Bun ingestion worker\nParse + chunk + index documents", fillcolor="#DAF1E4", color="#76B894"];
 {rank=same; rw; iw}
 }

 subgraph cluster_ai {
 label="05 / AI ORCHESTRATION & RETRIEVAL"; labelloc=t; labeljust=l; fontsize=14;
 style="rounded,filled"; color="#D1E8DC"; fillcolor="#F3FBF6"; margin=17;
 graph [rank=same];
 agent [label="LangGraph.js orchestrator\nPlan · Research · Verify · Report\nHuman-in-the-loop", fillcolor="#DAF1E4", color="#76B894"];
 rag [label="Advanced retrieval engine\nDense + BM25 · RRF · Rerank\nGraph expansion + citations", fillcolor="#DAF1E4", color="#76B894"];
 }

 subgraph cluster_data {
 label="06 / PERSISTENCE & KNOWLEDGE"; labelloc=t; labeljust=l; fontsize=14;
 style="rounded,filled"; color="#F0E0BB"; fillcolor="#FFFBF3"; margin=17;
 pg [label="PostgreSQL\nUsers · Reports · Sessions\nLangGraph checkpoints", fillcolor="#FFF0D1", color="#D9B469"];
 qdrant [label="Qdrant\nDense + sparse vectors\nDocument chunks", fillcolor="#FFF0D1", color="#D9B469"];
 neo [label="Neo4j\nEntities · Relationships\nClaims + provenance", fillcolor="#FFF0D1", color="#D9B469"];
 obj [label="S3 / MinIO\nOriginal source documents", fillcolor="#FFF0D1", color="#D9B469"];
 {rank=same; pg; qdrant; neo; obj}
 }

 subgraph cluster_external {
 label="07 / EXTERNAL SERVICES"; labelloc=t; labeljust=l; fontsize=14;
 style="rounded,filled"; color="#D6DEE9"; fillcolor="#F8FAFC"; margin=17;
 llm [label="LLM + embedding providers", fillcolor="#F0F4F9"];
 web [label="Web search + crawling", fillcolor="#F0F4F9"];
 obs [label="LangSmith + structured logs", fillcolor="#F0F4F9"];
 {rank=same; llm; web; obs}
 }

 user -> ui [label="research / upload"];
 ui -> api [label="HTTPS / REST"];
 api -> valkey [label="enqueue"];
 valkey -> rw [label="consume"];
 valkey -> iw [label="consume"];
 rw -> agent [label="execute"];
 agent -> rag [label="retrieve"];
 rag -> qdrant [label="hybrid search"];
 rag -> neo [label="graph traversal"];
 iw -> obj [label="persist", color="#D3AE68", fontcolor="#A78138", constraint=false];
 iw -> qdrant [label="index", color="#D3AE68", fontcolor="#A78138", constraint=false];
 iw -> neo [label="extract graph", color="#D3AE68", fontcolor="#A78138", constraint=false];
 api -> pg [label="application data", style=dashed, constraint=false, color="#D3AE68"];
 agent -> pg [label="checkpoint / reports", style=dashed, constraint=false, color="#D3AE68"];
 agent -> llm [label="inference", style=dashed];
 agent -> web [label="discovery", style=dashed];
 valkey -> sse [label="progress events", style=dashed, constraint=false];
 sse -> ui [label="SSE updates", style=dashed, constraint=false];
 rw -> obs [style=dotted, constraint=false];
 iw -> obs [style=dotted, constraint=false];
 api -> obs [style=dotted, constraint=false];
}
"}
